def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Gather opponent action string and key stats
    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    last_mine = my[-1]
    last_opp = opp[-1]

    # Opening: cooperate, then retaliate once if opponent defected.
    if n < 3:
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Detect a pure defector quickly and lock into defection with rare probes.
    if opp_d >= 4 and opp_c <= 1:
        if n % 9 == 0:
            return 'C'
        return 'D'

    # If opponent never defected, cooperate but add late-game exploitation
    # against overly-passive cooperators.
    if opp_d == 0:
        if n >= 92:
            # Against an unconditional cooperator, defect to grab 5s.
            return 'D'
        return 'C'

    # Endgame exploitation: if opponent's last action was C and they have
    # shown almost no retaliation to our prior defections, defect.
    if n >= 85:
        if last_opp == 'C':
            # Count opponent retaliation after our defections.
            missed = 0
            chances = 0
            for i in range(1, n):
                if my[i - 1] == 'D':
                    chances += 1
                    if opp[i] == 'C':
                        missed += 1
            if chances == 0 or (missed * 2 >= chances and rng.random() < 0.85):
                return 'D'
        return 'C'

    # Compute recent window stats.
    start = max(0, n - 8)
    rec_opp = opp[start:]
    rec_c = rec_opp.count('C')
    rec_d = len(rec_opp) - rec_c

    # If we've been defecting repeatedly and enemy still cooperates, exploit more.
    my_recent_d = my[start:].count('D')
    if last_opp == 'C' and my_recent_d >= 2 and opp_d * 3 < opp_c:
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    # Strong defector: punish hard, with rare reconciliation attempts.
    if opp_d * 2 > opp_c + len(rec_opp):
        if rec_d >= 2:
            return 'D'
        if last_opp == 'D':
            return 'D'
        # Opponent cooperated last but overall defected a lot: try to keep them
        # cooperating briefly, but defect when cooperative streak ends.
        if opp[-1] == 'C' and len(rec_opp) >= 3 and rec_c >= 3:
            return 'C'
        return 'D'

    # Tit-for-tat core with forgiveness and probing against mild defectors.
    if last_opp == 'D':
        # Forgive only if their recent defection rate is low.
        if rec_d <= 1 and opp_d * 4 < n:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    if last_mine == 'D':
        # We defected and they still cooperated: this could be exploited a bit,
        # but avoid pushing a forgiving opponent into permanent retaliation.
        if opp_d * 4 < n:
            if rng.random() < 0.35:
                return 'D'
        return 'C'

    # Both cooperated last round: keep cooperating, with rare probes.
    if n > 6 and rec_c >= 6 and rng.random() < 0.03:
        return 'D'
    return 'C'
